+
+  /* USER CODE BEGIN Init */
+
+  /* USER CODE END Init */
+
+  /* Configure the system clock */
+  SystemClock_Config();
+
+  /* USER CODE BEGIN SysInit */
+
+  /* USER CODE END SysInit */
+
+  /* Initialize all configured peripherals */
+  MX_GPIO_Init();
+  MX_ADC1_Init();
+  MX_I2C1_Init();
+  MX_TIM1_Init();
+  MX_USART1_UART_Init();
+  MX_USB_DEVICE_Init();
+  /* USER CODE BEGIN 2 */
+    BH1750_Init();
+    HAL_TIM_PWM_Start(&htim1, TIM_CHANNEL_1); // Khởi động PWM cho Servo
+    /* USER CODE END 2 */
+
+  /* Infinite loop */
+  /* USER CODE BEGIN WHILE */
+  while (1)
+    {
+      // Bật servo (90 độ), bơm và đèn trong 5 giây
+      __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, 75);     // Servo 90 độ
+      HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, GPIO_PIN_SET);   // Bật Bơm
+      HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);   // Bật Đèn
+      
+      // Đọc cảm biến
+      HAL_ADC_Start(&hadc1);
+      if(HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
+          soil_value = HAL_ADC_GetValue(&hadc1);
+      }
+      HAL_ADC_Stop(&hadc1);
+      lux = BH1750_Read();
+      
+      // Gửi dữ liệu lên PC
+      sprintf(msg, "[ON] Dat: %d | Anh sang: %.1f lux\r\n", soil_value, lux);
+      HAL_UART_Transmit(&huart1, (uint8_t*)msg, strlen(msg), 100);
+      
+      HAL_Delay(5000);
+
+      // Tắt servo (0 độ), bơm và đèn trong 5 giây
+      __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, 50);     // Servo 0 độ
+      HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, GPIO_PIN_RESET); // Tắt Bơm
+      HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET); // Tắt Đèn
+      
+      // Đọc cảm biến
+      HAL_ADC_Start(&hadc1);
+      if(HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
+          soil_value = HAL_ADC_GetValue(&hadc1);
+      }
+      HAL_ADC_Stop(&hadc1);
+      lux = BH1750_Read();
+      
+      // Gửi dữ liệu lên PC
+      sprintf(msg, "[OFF] Dat: %d | Anh sang: %.1f lux\r\n", soil_value, lux);
+      HAL_UART_Transmit(&huart1, (uint8_t*)msg, strlen(msg), 100);
+      
+      HAL_Delay(5000);
+    /* USER CODE END WHILE */
+
+    /* USER CODE BEGIN 3 */
+  }
+  /* USER CODE END 3 */
+}
