+  MX_TIM1_Init();
+  MX_USART1_UART_Init();
+  MX_USB_DEVICE_Init();
+  /* USER CODE BEGIN 2 */
+  BH1750_Init();
+  HAL_TIM_PWM_Start(&htim1, TIM_CHANNEL_1); // Khởi động PWM cho Servo
+    /* USER CODE END 2 */
+
+  /* Infinite loop */
+  /* USER CODE BEGIN WHILE */
+  while (1)
+  {
+    // Quay CW đầy tải trong 1 giây để đạt 360°
+    __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, 50);     // ~1ms xung: Quay CW
+    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, GPIO_PIN_SET);   // Bật Bơm
+    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);   // Bật Đèn
+    
+    // Đọc cảm biến
+    HAL_ADC_Start(&hadc1);
+    if(HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
+        soil_value = HAL_ADC_GetValue(&hadc1);
+    }
+    HAL_ADC_Stop(&hadc1);
+    lux = BH1750_Read();
+    
+    // Gửi dữ liệu lên PC
+    sprintf(msg, "[CW 360°] Dat: %d | Anh sang: %.1f lux\r\n", soil_value, lux);
+    HAL_UART_Transmit(&huart1, (uint8_t*)msg, strlen(msg), 100);
+    
+    HAL_Delay(1000);  // Trễ 1 giây để quay 360° (hiệu chỉnh nếu tốc độ khác)
+
+    // Dừng quay
+    __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, 75);     // ~1.5ms xung: Dừng
+    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, GPIO_PIN_RESET); // Tắt Bơm
+    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET); // Tắt Đèn
+    
+    // Đọc cảm biến
+    HAL_ADC_Start(&hadc1);
+    if(HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
+        soil_value = HAL_ADC_GetValue(&hadc1);
+    }
+    HAL_ADC_Stop(&hadc1);
+    lux = BH1750_Read();
+    
+    // Gửi dữ liệu lên PC
+    sprintf(msg, "[STOP] Dat: %d | Anh sang: %.1f lux\r\n", soil_value, lux);
+    HAL_UART_Transmit(&huart1, (uint8_t*)msg, strlen(msg), 100);
+    
+    HAL_Delay(5000);  // Nghỉ 5 giây trước khi lặp lại
+  /* USER CODE END WHILE */
+
+    /* USER CODE BEGIN 3 */
+  }
+  /* USER CODE END 3 */
+}
