+void BH1750_Init() {
+    uint8_t cmd = 0x01; // Power on
+    HAL_I2C_Master_Transmit(&hi2c1, 0x46, &cmd, 1, 100);
+    cmd = 0x10; // Continuously H-Resolution Mode
+    HAL_I2C_Master_Transmit(&hi2c1, 0x46, &cmd, 1, 100);
+}
+
+float BH1750_Read() {
+    if (HAL_I2C_Master_Receive(&hi2c1, 0x47, bh1750_data, 2, 100) == HAL_OK) {
+        uint16_t raw = (bh1750_data[0] << 8) | bh1750_data[1];
+        return raw / 1.2;
+    }
+    return -1;
+}
